keyframes.css:
@keyframes fd-dialog-in { 
  0% { opacity: 0; transform: scale(1.06); }
  100% { transform: scale(1); }
}

@keyframes fd-dialog-out { 
  0% { transform: scale(1); }
  100% { opacity: 0; transform: scale(1.04); }
}

@keyframes fd-enterFromRight { 
  0% { opacity: 0; transform: translate(200px); }
  100% { opacity: 1; transform: translate(0px); }
}

@keyframes fd-enterFromLeft { 
  0% { opacity: 0; transform: translate(-200px); }
  100% { opacity: 1; transform: translate(0px); }
}

@keyframes fd-exitToRight { 
  0% { opacity: 1; transform: translate(0px); }
  100% { opacity: 0; transform: translate(200px); }
}

@keyframes fd-exitToLeft { 
  0% { opacity: 1; transform: translate(0px); }
  100% { opacity: 0; transform: translate(-200px); }
}

@keyframes fd-ai-slide-up { 
  0% { opacity: 0; transform: translate(-50%, -48%) scale(0.96); }
  100% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
}

@keyframes fd-ai-float-in { 
  0% { opacity: 0; transform: translateY(12px) scale(0.95); }
  100% { opacity: 1; transform: translateY(0px) scale(1); }
}

@keyframes fd-ai-float-center-in { 
  0% { opacity: 0; transform: translate(-50%, -48%) scale(0.96); }
  100% { opacity: 1; transform: translate(-50%, -50%) scale(1); }
}

@keyframes fd-ai-msg-in { 
  0% { opacity: 0; transform: translateY(6px); }
  100% { opacity: 1; transform: translateY(0px); }
}

@keyframes fd-ai-loader-in { 
  0% { opacity: 0; transform: translateY(4px); }
  100% { opacity: 1; transform: translateY(0px); }
}

@keyframes fd-ai-typing { 
  0%, 100% { opacity: 0.5; transform: translateY(0px); }
  50% { opacity: 1; transform: translateY(-2px); }
}

@keyframes fd-ai-bounce-dots { 
  0%, 100% { opacity: 0.5; transform: scale(0.8); }
  50% { opacity: 1; transform: scale(1.2); }
}

@keyframes fd-ai-pulse { 
  0%, 100% { opacity: 0.8; transform: scale(0.95); }
  50% { opacity: 0.4; transform: scale(1.05); }
}

@keyframes fd-ai-pulse-dot { 
  0%, 100% { opacity: 0.8; transform: scale(1); }
  50% { opacity: 1; transform: scale(1.5); }
}

@keyframes fd-ai-wave-bars { 
  0%, 100% { opacity: 0.5; transform: scaleY(1); }
  50% { opacity: 1; transform: scaleY(0.6); }
}

@keyframes omni-scale-in { 
  0% { opacity: 0; transform: translate(-50%) scale(0.98) translateY(-6px); }
  100% { opacity: 1; transform: translate(-50%) scale(1) translateY(0px); }
}

@keyframes omni-scale-out { 
  0% { opacity: 1; transform: translate(-50%) scale(1) translateY(0px); }
  100% { opacity: 0; transform: translate(-50%) scale(0.98) translateY(-6px); }
}

@keyframes fd-page-actions-fade-in { 
  0% { opacity: 0; transform: translateY(-4px); }
  100% { opacity: 1; transform: translateY(0px); }
}

@keyframes fd-slide-up { 
  0% { opacity: 0; transform: translateY(8px) scale(0.98); }
  100% { opacity: 1; transform: translateY(0px) scale(1); }
}

@keyframes farm-terminal-command-type { 
  0% { opacity: 1; width: 0px; }
  2% { opacity: 1; width: 0px; animation-timing-function: steps(8); }
  7%, 88% { opacity: 1; width: 8ch; }
  94%, 99.99% { opacity: 0; width: 8ch; }
  100% { opacity: 1; width: 0px; }
}

@keyframes farm-terminal-output { 
  0%, 12% { clip-path: inset(0px 0px 100%); opacity: 1; animation-timing-function: steps(6, start); }
  68%, 88% { clip-path: inset(0px); opacity: 1; animation-timing-function: linear; }
  94%, 99.99% { clip-path: inset(0px); opacity: 0; }
  100% { clip-path: inset(0px 0px 100%); opacity: 1; }
}

@keyframes farm-build-command-type { 
  0% { opacity: 1; width: 0px; }
  2% { opacity: 1; width: 0px; animation-timing-function: steps(26); }
  11%, 88% { opacity: 1; width: 26ch; }
  94%, 99.99% { opacity: 0; width: 26ch; }
  100% { opacity: 1; width: 0px; }
}

@keyframes farm-build-output { 
  0%, 14% { clip-path: inset(0px 0px 100%); opacity: 1; animation-timing-function: steps(5, start); }
  56%, 88% { clip-path: inset(0px); opacity: 1; animation-timing-function: linear; }
  94%, 99.99% { clip-path: inset(0px); opacity: 0; }
  100% { clip-path: inset(0px 0px 100%); opacity: 1; }
}

@keyframes farm-code-cycle-panel-in { 
  0% { opacity: 0; transform: translateY(4px); }
  100% { opacity: 1; transform: translate(0px, 0px); }
}

@keyframes benchmark-comparison-cycle { 
  0% { opacity: 0; transform: translateY(46%); }
  4%, 22% { opacity: 1; transform: translate(0px, 0px); }
  25%, 100% { opacity: 0; transform: translateY(-42%); }
}

@keyframes blog-ascii-wave { 
  0%, 100% { opacity: 0.65; transform: translate(-8px); }
  50% { opacity: 1; transform: translate(8px); }
}
